import socket, struct, threading, time, sys

HOST='127.0.0.1'; PORT=5300

def parse_name(msg, off):
    labels=[]
    jumped=False
    start=off
    while True:
        l=msg[off]
        if l==0:
            off+=1
            break
        if l & 0xC0 == 0xC0:
            ptr=((l & 0x3F)<<8)|msg[off+1]
            if not jumped:
                start=off+2
                jumped=True
            off=ptr
            continue
        off+=1
        labels.append(msg[off:off+l].decode('ascii'))
        off+=l
    return '.'.join(labels)+'.', (start if jumped else off)

def enc_name(name):
    if name=='.':
        return b'\x00'
    name=name.rstrip('.')
    out=b''
    for part in name.split('.'):
        out += bytes([len(part)]) + part.encode('ascii')
    return out + b'\x00'

def rr(name_wire, rtype, rclass, ttl, rdata):
    return name_wire + struct.pack('!HHIH', rtype, rclass, ttl, len(rdata)) + rdata

def a(ip):
    return socket.inet_aton(ip)

def aaaa(ip):
    return socket.inet_pton(socket.AF_INET6, ip)

def txt(*parts):
    out=b''
    for p in parts:
        b=p.encode('utf-8')
        out += bytes([len(b)]) + b
    return out

def mx(pref, host):
    return struct.pack('!H', pref) + enc_name(host)

def ns(host):
    return enc_name(host)

def cname(host):
    return enc_name(host)

def ptr(host):
    return enc_name(host)

def hinfo(cpu, os):
    return bytes([len(cpu)])+cpu.encode()+bytes([len(os)])+os.encode()

def soa(mname, rname, serial, refresh, retry, expire, minimum):
    return enc_name(mname)+enc_name(rname)+struct.pack('!IIIII', serial, refresh, retry, expire, minimum)

def srv(priority, weight, port, target):
    return struct.pack('!HHH', priority, weight, port)+enc_name(target)

def caa(flags, tag, value):
    tb=tag.encode('ascii'); vb=value.encode('ascii')
    return bytes([flags, len(tb)]) + tb + vb

def naptr(order, preference, flags, service, regexp, replacement):
    fb=flags.encode('ascii'); sb=service.encode('ascii'); rb=regexp.encode('ascii')
