+			case "version":
+				opts.version = true
+			case "query":
+				if !hasValue {
+					i++
+					if i >= len(args) {
+						return opts, errors.New("Missing value for option --query")
+					}
+					value = args[i]
+				}
+				opts.queries = append(opts.queries, value)
+			case "type":
+				if !hasValue {
+					i++
+					if i >= len(args) {
+						return opts, errors.New("Missing value for option --type")
+					}
+					value = args[i]
+				}
+				code, ok := parseTypeToken(value)
+				if !ok {
+					return opts, fmt.Errorf("Invalid query type %q", value)
+				}
+				opts.typeCodes = append(opts.typeCodes, code)
+			case "class":
+				if !hasValue {
+					i++
+					if i >= len(args) {
+						return opts, errors.New("Missing value for option --class")
+					}
+					value = args[i]
+				}
+				code, ok := parseClassToken(value)
+				if !ok {
+					return opts, fmt.Errorf("Invalid query class %q", value)
+				}
+				opts.classCodes = append(opts.classCodes, code)
+			case "nameserver":
+				if !hasValue {
+					i++
+					if i >= len(args) {
+						return opts, errors.New("Missing value for option --nameserver")
+					}
+					value = args[i]
+				}
+				opts.nameservers = append(opts.nameservers, value)
+			case "udp":
+				opts.transports = appendTransport(opts.transports, transportUDP)
+			case "tcp":
+				opts.transports = appendTransport(opts.transports, transportTCP)
+			case "tls":
+				opts.transports = appendTransport(opts.transports, transportTLS)
+			case "https":
+				opts.transports = appendTransport(opts.transports, transportHTTPS)
+			case "short":
+				opts.short = true
+			case "json":
+				opts.json = true
+			case "color", "colour":
+				if !hasValue {
+					i++
+					if i >= len(args) {
+						return opts, errors.New("Missing value for option --color")
+					}
+					value = args[i]
+				}
+				opts.color = value
+			case "seconds":
+				opts.seconds = true
+			case "time":
+				opts.time = true
+			case "edns":
+				if !hasValue {
+					i++
+					if i >= len(args) {
+						return opts, errors.New("Missing value for option --edns")
+					}
+					value = args[i]
+				}
+				switch value {
+				case "hide":
+					opts.edns = ednsHide
+				case "show":
+					opts.edns = ednsShow
+				case "disable":
+					opts.edns = ednsDisable
+				default:
+					return opts, fmt.Errorf("Invalid EDNS setting %q", value)
+				}
+			case "txid":
+				if !hasValue {
+					i++
+					if i >= len(args) {
+						return opts, errors.New("Missing value for option --txid")
+					}
+					value = args[i]
+				}
+				v, ok := parseUint16Strict(value)
+				if !ok {
+					return opts, fmt.Errorf("Invalid transaction ID %q", value)
+				}
+				opts.txid = &v
+			default:
+				return opts, fmt.Errorf("Unrecognized option: %q", strings.TrimPrefix(name, "--"))
+			}
+			i++
+			continue
+		}
+		if strings.HasPrefix(arg, "-") && arg != "-" {
+			if arg == "-?" {
+				opts.help = true
+				i++
+				continue
+			}
+			if arg == "-v" {
+				opts.version = true
+				i++
+				continue
+			}
+			if arg == "-1" {
+				opts.short = true
+				i++
+				continue
+			}
+			cluster := arg[1:]
+			consumedValue := false
+			for len(cluster) > 0 {
+				ch := cluster[0]
+				cluster = cluster[1:]
+				switch ch {
+				case '?':
+					opts.help = true
+				case 'v':
+					opts.version = true
+				case '1':
+					opts.short = true
+				case 'J':
+					opts.json = true
+				case 'U':
+					opts.transports = appendTransport(opts.transports, transportUDP)
+				case 'T':
+					opts.transports = appendTransport(opts.transports, transportTCP)
+				case 'S':
+					opts.transports = appendTransport(opts.transports, transportTLS)
+				case 'H':
+					opts.transports = appendTransport(opts.transports, transportHTTPS)
+				case 'q', 't', 'n', 'Z':
+					value := cluster
+					if value == "" {
+						i++
+						if i >= len(args) {
+							return opts, fmt.Errorf("Missing value for option -%c", ch)
+						}
+						value = args[i]
+					}
+					cluster = ""
+					consumedValue = true
+					switch ch {
+					case 'q':
+						opts.queries = append(opts.queries, value)
+					case 't':
+						code, ok := parseTypeToken(value)
+						if !ok {
+							return opts, fmt.Errorf("Invalid query type %q", value)
+						}
+						opts.typeCodes = append(opts.typeCodes, code)
+					case 'n':
+						opts.nameservers = append(opts.nameservers, value)
+					case 'Z':
+						if err := applyTweak(&opts.tweaks, value); err != nil {
+							return opts, err
+						}
+					}
+				default:
+					return opts, fmt.Errorf("Unrecognized option: %q", string(ch))
+				}
+			}
+			i++
+			if consumedValue {
+				continue
+			}
+			continue
+		}
+		positional = append(positional, arg)
+		i++
+	}
+
+	for _, arg := range positional {
+		if strings.HasPrefix(arg, "@") {
+			opts.nameservers = append(opts.nameservers, arg[1:])
+			continue
+		}
+		if code, ok := parseTypeToken(arg); ok {
+			opts.typeCodes = append(opts.typeCodes, code)
+			continue
+		}
+		if code, ok := parseClassToken(arg); ok {
+			opts.classCodes = append(opts.classCodes, code)
+			continue
+		}
+		opts.queries = append(opts.queries, arg)
+	}
+
+	return opts, nil
+}
+
+func splitLong(arg string) (string, string, bool) {
+	name := arg
+	value := ""
+	hasValue := false
+	if eq := strings.IndexByte(arg, '='); eq >= 0 {
+		name = arg[:eq]
+		value = arg[eq+1:]
+		hasValue = true
+	}
+	return strings.TrimPrefix(name, "--"), value, hasValue
+}
+
+func appendTransport(in []transport, t transport) []transport {
+	for _, existing := range in {
+		if existing == t {
+			return in
+		}
+	}
+	return append(in, t)
+}
+
+func applyTweak(t *protocolTweaks, value string) error {
+	switch {
+	case value == "aa":
+		t.setAA = true
+	case value == "ad":
+		t.setAD = true
+	case value == "cd":
+		t.setCD = true
+	case strings.HasPrefix(value, "bufsize="):
+		n, ok := parseUint16Strict(strings.TrimPrefix(value, "bufsize="))
+		if !ok {
+			return fmt.Errorf("Invalid protocol tweak %q", value)
+		}
+		t.bufsize = n
+		t.hasBufsz = true
+	default:
+		return fmt.Errorf("Invalid protocol tweak %q", value)
+	}
+	return nil
+}
+
+func parseUint16Strict(s string) (uint16, bool) {
+	n, err := strconv.ParseUint(s, 10, 16)
+	if err != nil {
+		return 0, false
+	}
+	return uint16(n), true
+}
+
+func buildSpecs(opts options) ([]querySpec, int, error) {
+	typeCodes := opts.typeCodes
+	if len(typeCodes) == 0 {
+		typeCodes = []uint16{1}
+	}
+	classCodes := opts.classCodes
+	if len(classCodes) == 0 {
+		classCodes = []uint16{1}
+	}
+
+	nameservers := make([]string, 0, len(opts.nameservers))
+	if len(opts.nameservers) == 0 {
+		var err error
+		nameservers, err = readSystemNameservers()
+		if err != nil {
+			return nil, exitNameserverInfo, err
+		}
+	} else {
+		nameservers = append(nameservers, opts.nameservers...)
+	}
+
+	transports := orderedTransports(opts.transports)
+	if len(transports) == 0 {
+		transports = []transport{transportAutomatic}
+	}
+
+	if containsTransport(transports, transportHTTPS) {
+		if len(opts.nameservers) == 0 {
+			return nil, exitOptions, errors.New("You must pass a URL as a nameserver when using --https")
+		}
+		for _, ns := range nameservers {
+			if !isValidURL(ns) {
+				return nil, exitOptions, errors.New("You must pass a URL as a nameserver when using --https")
+			}
+		}
+	}
+
+	specs := make([]querySpec, 0, len(opts.queries)*len(typeCodes)*len(classCodes)*len(nameservers)*len(transports))
+	for _, domain := range opts.queries {
+		for _, typeCode := range typeCodes {
+			for _, classCode := range classCodes {
+				for _, nameserver := range nameservers {
+					for _, tr := range transports {
+						specs = append(specs, querySpec{
+							name:       normalizeName(domain),
+							typeCode:   typeCode,
+							classCode:  classCode,
+							nameserver: nameserver,
+							transport:  tr,
+						})
+					}
+				}
+			}
+		}
+	}
+	return specs, exitOK, nil
+}
+
+func orderedTransports(in []transport) []transport {
+	if len(in) == 0 {
+		return nil
+	}
+	order := []transport{transportHTTPS, transportTLS, transportTCP, transportUDP}
+	out := make([]transport, 0, len(in))
+	for _, want := range order {
+		for _, got := range in {
+			if got == want {
+				out = append(out, got)
+				break
+			}
+		}
+	}
+	return out
+}
+
+func containsTransport(in []transport, want transport) bool {
+	for _, got := range in {
+		if got == want {
+			return true
+		}
+	}
+	return false
+}
+
+func readSystemNameservers() ([]string, error) {
+	data, err := os.ReadFile("/etc/resolv.conf")
+	if err != nil {
+		return nil, err
+	}
+	lines := strings.Split(string(data), "\n")
+	out := make([]string, 0)
+	for _, line := range lines {
+		line = strings.TrimSpace(line)
+		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
+			continue
+		}
+		fields := strings.Fields(line)
+		if len(fields) >= 2 && fields[0] == "nameserver" {
+			out = append(out, fields[1])
+		}
+	}
+	if len(out) == 0 {
+		return nil, errors.New("No nameserver information found")
+	}
+	return out, nil
+}
+
+func isValidURL(s string) bool {
+	u, err := url.Parse(s)
+	if err != nil {
+		return false
+	}
+	return u.Scheme != "" && u.Host != ""
+}
+
+func normalizeName(s string) string {
+	s = strings.TrimSpace(s)
+	if s == "" {
+		return s
+	}
+	if s == "." {
+		return s
+	}
+	return strings.TrimSuffix(s, ".") + "."
+}
+
+func executeQuery(spec querySpec, opts options) (*response, time.Duration, error) {
+	id := randomID()
+	if opts.txid != nil {
+		id = *opts.txid
+	}
+
+	req, err := buildQueryPacket(id, spec, opts)
+	if err != nil {
+		return nil, 0, err
+	}
+
+	start := time.Now()
+	switch spec.transport {
+	case transportAutomatic:
+		packet, err := queryUDP(spec.nameserver, req)
+		if err != nil {
+			return nil, time.Since(start), err
+		}
+		resp, err := parseResponse(packet)
+		if err != nil {
+			return nil, time.Since(start), err
+		}
+		if resp.Flags.TC {
+			packet, err = queryTCP(spec.nameserver, req, false)
+			if err != nil {
+				return nil, time.Since(start), err
+			}
+			resp, err = parseResponse(packet)
+			if err != nil {
+				return nil, time.Since(start), err
+			}
+		}
+		return resp, time.Since(start), nil
+	case transportUDP:
+		packet, err := queryUDP(spec.nameserver, req)
+		if err != nil {
+			return nil, time.Since(start), err
+		}
+		resp, err := parseResponse(packet)
+		return resp, time.Since(start), err
+	case transportTCP:
+		packet, err := queryTCP(spec.nameserver, req, false)
+		if err != nil {
+			return nil, time.Since(start), err
+		}
+		resp, err := parseResponse(packet)
+		return resp, time.Since(start), err
+	case transportTLS:
+		packet, err := queryTCP(spec.nameserver, req, true)
+		if err != nil {
+			return nil, time.Since(start), err
+		}
+		resp, err := parseResponse(packet)
+		return resp, time.Since(start), err
+	case transportHTTPS:
+		packet, err := queryHTTPS(spec.nameserver, req)
+		if err != nil {
+			return nil, time.Since(start), err
+		}
+		resp, err := parseResponse(packet)
+		return resp, time.Since(start), err
+	default:
+		return nil, time.Since(start), errors.New("unsupported transport")
+	}
+}
+
+func randomID() uint16 {
+	var b [2]byte
+	if _, err := rand.Read(b[:]); err == nil {
+		return binary.BigEndian.Uint16(b[:])
+	}
+	return uint16(mrand.Intn(65536))
+}
+
+func buildQueryPacket(id uint16, spec querySpec, opts options) ([]byte, error) {
+	var b builder
+	flags := uint16(0x0100)
+	if opts.tweaks.setAA {
+		flags |= 1 << 10
+	}
+	if opts.tweaks.setAD {
+		flags |= 1 << 5
+	}
+	if opts.tweaks.setCD {
+		flags |= 1 << 4
+	}
+
+	arcount := uint16(0)
+	if opts.edns != ednsDisable {
+		arcount = 1
+	}
+
+	b.u16(id)
+	b.u16(flags)
+	b.u16(1)
+	b.u16(0)
+	b.u16(0)
+	b.u16(arcount)
+	if err := b.name(spec.name); err != nil {
+		return nil, err
+	}
+	b.u16(spec.typeCode)
+	b.u16(spec.classCode)
+	if opts.edns != ednsDisable {
+		payload := uint16(512)
+		if opts.tweaks.hasBufsz {
+			payload = opts.tweaks.bufsize
+		}
+		b.u8(0)
+		b.u16(41)
+		b.u16(payload)
+		b.u32(0)
+		b.u16(0)
+	}
+	return b.bytes(), nil
+}
+
+type builder struct{ buf []byte }
+
+func (b *builder) u8(v uint8)   { b.buf = append(b.buf, v) }
+func (b *builder) u16(v uint16) { b.buf = binary.BigEndian.AppendUint16(b.buf, v) }
+func (b *builder) u32(v uint32) { b.buf = binary.BigEndian.AppendUint32(b.buf, v) }
+func (b *builder) bytes() []byte {
+	return append([]byte(nil), b.buf...)
+}
+
+func (b *builder) name(name string) error {
+	name = strings.TrimSuffix(name, ".")
+	if name == "" {
+		b.u8(0)
+		return nil
+	}
+	parts := strings.Split(name, ".")
+	for _, part := range parts {
+		if len(part) > 63 {
+			return fmt.Errorf("invalid label %q", part)
+		}
+		b.u8(uint8(len(part)))
+		b.buf = append(b.buf, part...)
+	}
+	b.u8(0)
+	return nil
+}
+
+func queryUDP(nameserver string, req []byte) ([]byte, error) {
+	addr := normalizeHostPort(nameserver, "53")
+	conn, err := net.DialTimeout("udp", addr, 2*time.Second)
+	if err != nil {
+		return nil, err
+	}
+	defer conn.Close()
+	_ = conn.SetDeadline(time.Now().Add(3 * time.Second))
+	if _, err := conn.Write(req); err != nil {
+		return nil, err
+	}
+	buf := make([]byte, 65535)
+	n, err := conn.Read(buf)
+	if err != nil {
+		return nil, err
+	}
+	return append([]byte(nil), buf[:n]...), nil
+}
+
+func queryTCP(nameserver string, req []byte, useTLS bool) ([]byte, error) {
+	addr := normalizeHostPort(nameserver, map[bool]string{true: "853", false: "53"}[useTLS])
+	var conn net.Conn
+	var err error
+	dialer := &net.Dialer{Timeout: 2 * time.Second}
+	if useTLS {
+		host := extractHost(addr)
+		cfg := &tls.Config{}
+		if host != "" && net.ParseIP(host) == nil {
+			cfg.ServerName = host
+		}
+		conn, err = tls.DialWithDialer(dialer, "tcp", addr, cfg)
+	} else {
+		conn, err = dialer.Dial("tcp", addr)
+	}
+	if err != nil {
+		return nil, err
+	}
+	defer conn.Close()
+	_ = conn.SetDeadline(time.Now().Add(3 * time.Second))
+
+	frame := make([]byte, 2+len(req))
+	binary.BigEndian.PutUint16(frame[:2], uint16(len(req)))
+	copy(frame[2:], req)
+	if _, err := conn.Write(frame); err != nil {
+		return nil, err
+	}
+
+	header := make([]byte, 2)
+	if _, err := io.ReadFull(conn, header); err != nil {
+		return nil, err
+	}
+	n := int(binary.BigEndian.Uint16(header))
+	buf := make([]byte, n)
+	if _, err := io.ReadFull(conn, buf); err != nil {
+		return nil, err
+	}
+	return buf, nil
+}
+
+func queryHTTPS(endpoint string, req []byte) ([]byte, error) {
+	client := &http.Client{
+		Timeout: 4 * time.Second,
+	}
+	httpReq, err := http.NewRequest(http.MethodPost, endpoint, strings.NewReader(string(req)))
+	if err != nil {
+		return nil, err
+	}
+	httpReq.Header.Set("Content-Type", "application/dns-message")
+	httpReq.Header.Set("Accept", "application/dns-message")
+	resp, err := client.Do(httpReq)
+	if err != nil {
+		return nil, err
+	}
+	defer resp.Body.Close()
+	if resp.StatusCode != http.StatusOK {
+		return nil, fmt.Errorf("unexpected HTTP status %s", resp.Status)
+	}
+	return io.ReadAll(resp.Body)
+}
+
+func normalizeHostPort(input, defaultPort string) string {
+	if _, err := netip.ParseAddr(input); err == nil {
+		return net.JoinHostPort(input, defaultPort)
+	}
+	if host, port, err := net.SplitHostPort(input); err == nil {
+		if host == "" {
+			return net.JoinHostPort(host, defaultPort)
+		}
+		return net.JoinHostPort(host, port)
+	}
+	if strings.HasPrefix(input, "[") && strings.HasSuffix(input, "]") {
+		return net.JoinHostPort(strings.Trim(input, "[]"), defaultPort)
+	}
+	return net.JoinHostPort(input, defaultPort)
+}
+
+func extractHost(addr string) string {
+	host, _, err := net.SplitHostPort(addr)
+	if err != nil {
+		return addr
+	}
+	return host
+}
+
+type parser struct {
+	data []byte
+	off  int
+}
+
+func parseResponse(data []byte) (*response, error) {
+	if len(data) < 12 {
+		return nil, errors.New("response too short")
+	}
+	p := parser{data: data}
+	id := p.u16()
+	flagsVal := p.u16()
+	qdcount := int(p.u16())
+	ancount := int(p.u16())
+	nscount := int(p.u16())
+	arcount := int(p.u16())
+	resp := &response{
+		ID:    id,
+		Flags: decodeFlags(flagsVal),
+	}
+	resp.Questions = make([]question, 0, qdcount)
+	resp.Answers = make([]rr, 0, ancount)
+	resp.Authorities = make([]rr, 0, nscount)
+	resp.Additionals = make([]rr, 0, arcount)
+	for i := 0; i < qdcount; i++ {
+		name, err := p.name()
+		if err != nil {
+			return nil, err
+		}
+		resp.Questions = append(resp.Questions, question{
+			Name:  name,
+			Type:  p.u16(),
+			Class: p.u16(),
+		})
+	}
+	for i := 0; i < ancount; i++ {
+		record, err := p.record()
+		if err != nil {
+			return nil, err
+		}
+		resp.Answers = append(resp.Answers, record)
+	}
+	for i := 0; i < nscount; i++ {
+		record, err := p.record()
+		if err != nil {
+			return nil, err
+		}
+		resp.Authorities = append(resp.Authorities, record)
+	}
+	for i := 0; i < arcount; i++ {
+		record, err := p.record()
+		if err != nil {
+			return nil, err
+		}
+		resp.Additionals = append(resp.Additionals, record)
+	}
+	return resp, nil
+}
+
+func decodeFlags(v uint16) packetFlags {
+	return packetFlags{
+		QR:     v&(1<<15) != 0,
+		Opcode: (v >> 11) & 0xF,
+		AA:     v&(1<<10) != 0,
+		TC:     v&(1<<9) != 0,
+		RD:     v&(1<<8) != 0,
+		RA:     v&(1<<7) != 0,
+		AD:     v&(1<<5) != 0,
+		CD:     v&(1<<4) != 0,
+		RCode:  v & 0xF,
+	}
+}
+
+func (p *parser) u16() uint16 {
+	v := binary.BigEndian.Uint16(p.data[p.off:])
+	p.off += 2
+	return v
+}
+
+func (p *parser) u32() uint32 {
+	v := binary.BigEndian.Uint32(p.data[p.off:])
+	p.off += 4
+	return v
+}
+
+func (p *parser) bytes(n int) []byte {
+	v := p.data[p.off : p.off+n]
+	p.off += n
+	return v
+}
+
+func (p *parser) name() (string, error) {
+	name, next, err := parseName(p.data, p.off, 0)
+	if err != nil {
+		return "", err
+	}
+	p.off = next
+	return name, nil
+}
+
+func parseName(data []byte, off int, depth int) (string, int, error) {
+	if depth > 16 {
+		return "", off, errors.New("name compression loop")
+	}
+	parts := make([]string, 0)
+	start := off
+	jumped := false
+	for {
+		if off >= len(data) {
+			return "", start, io.ErrUnexpectedEOF
+		}
+		l := int(data[off])
+		switch {
+		case l == 0:
+			off++
+			if !jumped {
+				start = off
+			}
+			if len(parts) == 0 {
+				return "", start, nil
+			}
+			return strings.Join(parts, ".") + ".", start, nil
+		case l&0xC0 == 0xC0:
+			if off+1 >= len(data) {
+				return "", start, io.ErrUnexpectedEOF
+			}
+			ptr := int(binary.BigEndian.Uint16(data[off:off+2]) & 0x3FFF)
+			name, _, err := parseName(data, ptr, depth+1)
+			if err != nil {
+				return "", start, err
+			}
+			if name != "" {
+				parts = append(parts, strings.TrimSuffix(name, "."))
+			}
+			off += 2
+			if !jumped {
+				start = off
+			}
+			jumped = true
+			return strings.Join(parts, ".") + ".", start, nil
+		default:
+			off++
+			if off+l > len(data) {
+				return "", start, io.ErrUnexpectedEOF
+			}
+			parts = append(parts, string(data[off:off+l]))
+			off += l
+			if !jumped {
+				start = off
+			}
+		}
+	}
+}
+
+func (p *parser) record() (rr, error) {
+	name, err := p.name()
+	if err != nil {
+		return rr{}, err
+	}
+	typ := p.u16()
+	class := p.u16()
+	ttl := p.u32()
+	rdlen := int(p.u16())
+	if p.off+rdlen > len(p.data) {
+		return rr{}, io.ErrUnexpectedEOF
+	}
+	start := p.off
+	data := p.data[start : start+rdlen]
+	p.off += rdlen
+
+	record := rr{Name: name, Type: typ, Class: class, TTL: ttl}
+	switch typ {
+	case 1:
+		if len(data) == 4 {
+			record.Data = aData{Address: net.IP(data).String()}
+		}
+	case 28:
+		if len(data) == 16 {
+			record.Data = aaaaData{Address: net.IP(data).String()}
+		}
+	case 2:
+		ns, _, err := parseName(p.data, start, 0)
+		if err != nil {
+			return rr{}, err
+		}
+		record.Data = nsData{Nameserver: ns}
+	case 5:
+		cname, _, err := parseName(p.data, start, 0)
+		if err != nil {
+			return rr{}, err
+		}
+		record.Data = cnameData{Domain: cname}
+	case 12:
+		ptr, _, err := parseName(p.data, start, 0)
+		if err != nil {
+			return rr{}, err
+		}
+		record.Data = ptrData{CNAME: ptr}
+	case 15:
+		if len(data) < 2 {
+			return rr{}, io.ErrUnexpectedEOF
+		}
+		exchange, _, err := parseName(p.data, start+2, 0)
+		if err != nil {
+			return rr{}, err
+		}
+		record.Data = mxData{
+			Preference: binary.BigEndian.Uint16(data[:2]),
+			Exchange:   exchange,
+		}
+	case 16:
+		record.Data = txtData{Messages: parseTXT(data)}
+	case 13:
+		if len(data) >= 2 {
+			cpuLen := int(data[0])
+			if 1+cpuLen < len(data) {
+				osLen := int(data[1+cpuLen])
+				if 2+cpuLen+osLen <= len(data) {
+					record.Data = hinfoData{
+						CPU: string(data[1 : 1+cpuLen]),
+						OS:  string(data[2+cpuLen : 2+cpuLen+osLen]),
+					}
+				}
+			}
+		}
+	case 6:
+		mname, pos, err := parseName(p.data, start, 0)
+		if err != nil {
+			return rr{}, err
+		}
+		rname, pos, err := parseName(p.data, pos, 0)
+		if err != nil {
+			return rr{}, err
+		}
+		if pos+20 > len(p.data) {
+			return rr{}, io.ErrUnexpectedEOF
+		}
+		record.Data = soaData{
+			MName:   mname,
+			RName:   rname,
+			Serial:  binary.BigEndian.Uint32(p.data[pos : pos+4]),
+			Refresh: binary.BigEndian.Uint32(p.data[pos+4 : pos+8]),
+			Retry:   binary.BigEndian.Uint32(p.data[pos+8 : pos+12]),
+			Expire:  binary.BigEndian.Uint32(p.data[pos+12 : pos+16]),
+			Minimum: binary.BigEndian.Uint32(p.data[pos+16 : pos+20]),
+		}
+	case 33:
+		if len(data) < 6 {
+			return rr{}, io.ErrUnexpectedEOF
+		}
+		target, _, err := parseName(p.data, start+6, 0)
+		if err != nil {
+			return rr{}, err
+		}
+		record.Data = srvData{
+			Priority: binary.BigEndian.Uint16(data[:2]),
+			Weight:   binary.BigEndian.Uint16(data[2:4]),
+			Port:     binary.BigEndian.Uint16(data[4:6]),
+			Target:   target,
+		}
+	case 257:
+		if len(data) >= 2 {
+			tagLen := int(data[1])
+			if 2+tagLen <= len(data) {
+				record.Data = caaData{
+					Critical: data[0]&0x80 != 0,
+					Tag:      string(data[2 : 2+tagLen]),
+					Value:    string(data[2+tagLen:]),
+				}
+			}
+		}
+	case 35:
+		if len(data) >= 4 {
+			pos := start
+			order := binary.BigEndian.Uint16(p.data[pos : pos+2])
+			preference := binary.BigEndian.Uint16(p.data[pos+2 : pos+4])
+			pos += 4
+			flags, pos2, err := parseCharString(p.data, pos)
+			if err != nil {
+				return rr{}, err
+			}
+			service, pos3, err := parseCharString(p.data, pos2)
+			if err != nil {
+				return rr{}, err
+			}
+			regex, pos4, err := parseCharString(p.data, pos3)
+			if err != nil {
+				return rr{}, err
+			}
+			replacement, _, err := parseName(p.data, pos4, 0)
+			if err != nil {
+				return rr{}, err
+			}
+			record.Data = naptrData{
+				Order:       order,
+				Preference:  preference,
+				Flags:       flags,
+				Service:     service,
+				Regexp:      regex,
+				Replacement: replacement,
+			}
+		}
+	case 44:
+		if len(data) >= 2 {
+			record.Data = sshfpData{
+				Algorithm:       data[0],
+				FingerprintType: data[1],
+				Fingerprint:     strings.ToLower(fmt.Sprintf("%x", data[2:])),
+			}
+		}
+	case 52:
+		if len(data) >= 3 {
+			record.Data = tlsaData{
+				CertificateUsage: data[0],
+				Selector:         data[1],
+				MatchingType:     data[2],
+				CertificateData:  strings.ToLower(fmt.Sprintf("%x", data[3:])),
+			}
+		}
+	case 29:
+		if len(data) == 16 {
+			record.Data = parseLOC(data)
+		}
+	case 41:
+		opt := optRecord{
+			UDPPSize: uint16(class),
+			ExtCode:  uint8(ttl >> 24),
+			Version:  uint8((ttl >> 16) & 0xFF),
+			Flags:    uint16(ttl & 0xFFFF),
+		}
+		options := make([]ednsOption, 0)
+		pos := 0
+		for pos+4 <= len(data) {
+			code := binary.BigEndian.Uint16(data[pos : pos+2])
+			l := int(binary.BigEndian.Uint16(data[pos+2 : pos+4]))
+			pos += 4
+			if pos+l > len(data) {
+				break
+			}
+			options = append(options, ednsOption{Code: code, Data: append([]byte(nil), data[pos:pos+l]...)})
+			pos += l
+		}
+		opt.Options = options
+		record.Data = opt
+	default:
+		record.Data = unknownData{Bytes: append([]byte(nil), data...)}
+	}
+	if record.Data == nil {
+		record.Data = unknownData{Bytes: append([]byte(nil), data...)}
+	}
+	return record, nil
+}
+
+func parseTXT(data []byte) []string {
+	out := make([]string, 0)
+	for i := 0; i < len(data); {
+		l := int(data[i])
+		i++
+		if i+l > len(data) {
+			break
+		}
+		out = append(out, string(data[i:i+l]))
+		i += l
+	}
+	return out
+}
+
+func parseCharString(data []byte, off int) (string, int, error) {
+	if off >= len(data) {
+		return "", off, io.ErrUnexpectedEOF
+	}
+	l := int(data[off])
+	off++
+	if off+l > len(data) {
+		return "", off, io.ErrUnexpectedEOF
+	}
+	return string(data[off : off+l]), off + l, nil
+}
+
+func parseLOC(data []byte) locData {
+	size := fmt.Sprintf("%de%d", data[1]>>4, data[1]&0x0F)
+	lat := binary.BigEndian.Uint32(data[4:8])
+	lon := binary.BigEndian.Uint32(data[8:12])
+	alt := binary.BigEndian.Uint32(data[12:16])
+	return locData{
+		Size:                size,
+		HorizontalPrecision: data[2],
+		VerticalPrecision:   data[3],
+		Latitude:            formatLOCPosition(lat, true),
+		Longitude:           formatLOCPosition(lon, false),
+		Altitude:            formatLOCAltitude(alt),
+	}
+}
+
+func formatLOCPosition(raw uint32, latitude bool) string {
+	v := int64(raw) - (1 << 31)
+	dir := "N"
+	if !latitude {
+		dir = "E"
+	}
+	if v < 0 {
+		v = -v
+		if latitude {
+			dir = "S"
+		} else {
+			dir = "W"
+		}
+	}
+	totalMillis := v
+	deg := totalMillis / (1000 * 60 * 60)
+	totalMillis -= deg * 1000 * 60 * 60
+	min := totalMillis / (1000 * 60)
+	totalMillis -= min * 1000 * 60
+	secWhole := totalMillis / 1000
+	secFrac := totalMillis % 1000
+	if secFrac == 0 {
+		return fmt.Sprintf("%d\u00b0%d\u2032%d\u2033 %s", deg, min, secWhole, dir)
+	}
+	return fmt.Sprintf("%d\u00b0%d\u2032%d.%03d\u2033 %s", deg, min, secWhole, secFrac, dir)
+}
+
+func formatLOCAltitude(raw uint32) string {
+	cm := int64(raw) - 10000000
+	sign := ""
+	if cm < 0 {
+		sign = "-"
+		cm = -cm
+	}
+	return fmt.Sprintf("%s%d.%02dm", sign, cm/100, cm%100)
+}
+
+func renderShort(results []result) []string {
+	out := make([]string, 0)
+	for _, res := range results {
+		if res.resp == nil {
+			continue
+		}
+		for _, answer := range res.resp.Answers {
+			out = append(out, renderRData(answer, false))
+		}
+	}
+	return out
+}
+
+func renderText(w io.Writer, results []result, opts options, total time.Duration) {
+	rows := make([]row, 0)
+	status := ""
+	for _, res := range results {
+		if res.resp == nil {
+			continue
+		}
+		if status == "" && res.resp.Flags.RCode != 0 {
+			status = rcodeText(res.resp.Flags.RCode)
+		}
+		for _, answer := range res.resp.Answers {
+			if answer.Type == 41 && opts.edns != ednsShow {
+				continue
+			}
+			rows = append(rows, makeRow(answer, " ", opts))
+		}
+		for _, authority := range res.resp.Authorities {
+			if authority.Type == 41 && opts.edns != ednsShow {
+				continue
+			}
+			rows = append(rows, makeRow(authority, "A", opts))
+		}
+		for _, additional := range res.resp.Additionals {
+			if additional.Type == 41 && opts.edns != ednsShow {
+				continue
+			}
+			rows = append(rows, makeRow(additional, "+", opts))
+		}
+	}
+
+	if status != "" {
+		fmt.Fprintf(w, "Status: %s\n", status)
+	}
+	if len(rows) > 0 {
+		tw, nw, ttlw := 0, 0, 0
+		for _, r := range rows {
+			tw = max(tw, utf8.RuneCountInString(r.Type))
+			nw = max(nw, utf8.RuneCountInString(r.Name))
+			ttlw = max(ttlw, utf8.RuneCountInString(r.TTL))
+		}
+		for _, r := range rows {
+			fmt.Fprintf(w, "%-*s %-*s %-*s %s %s\n", tw, r.Type, nw, r.Name, ttlw, r.TTL, r.Marker, r.Data)
+		}
+	}
+	if opts.time {
+		fmt.Fprintf(w, "Ran in %dms\n", total.Milliseconds())
+	}
+}
+
+func makeRow(record rr, marker string, opts options) row {
+	ttl := ""
+	if record.Type != 41 {
+		if opts.seconds {
+			ttl = strconv.FormatUint(uint64(record.TTL), 10)
+		} else {
+			ttl = formatCompactDuration(record.TTL)
+		}
+	}
+	name := record.Name
+	if record.Type == 41 {
+		name = ""
+	}
+	return row{
+		Type:   typeName(record.Type),
+		Name:   name,
+		TTL:    ttl,
+		Marker: marker,
+		Data:   renderRData(record, opts.seconds),
+	}
+}
+
+func renderRData(record rr, seconds bool) string {
+	switch v := record.Data.(type) {
+	case aData:
+		return v.Address
+	case aaaaData:
+		return v.Address
+	case cnameData:
+		return quote(v.Domain)
+	case nsData:
+		return quote(v.Nameserver)
+	case ptrData:
+		return quote(v.CNAME)
+	case mxData:
+		return fmt.Sprintf("%d %s", v.Preference, quote(v.Exchange))
+	case txtData:
+		parts := make([]string, len(v.Messages))
+		for i, msg := range v.Messages {
+			parts[i] = quote(msg)
+		}
+		return strings.Join(parts, ", ")
+	case hinfoData:
+		return fmt.Sprintf("%s %s", quote(v.CPU), quote(v.OS))
+	case soaData:
+		return fmt.Sprintf("%s %s %d %s %s %s %s",
+			quote(v.MName),
+			quote(v.RName),
+			v.Serial,
+			formatRRDuration(v.Refresh, seconds),
+			formatRRDuration(v.Retry, seconds),
+			formatRRDuration(v.Expire, seconds),
+			formatRRDuration(v.Minimum, seconds),
+		)
+	case srvData:
+		return fmt.Sprintf("%d %d %s:%d", v.Priority, v.Weight, quote(v.Target), v.Port)
+	case caaData:
+		label := "non-critical"
+		if v.Critical {
+			label = "critical"
+		}
+		return fmt.Sprintf("%s %s (%s)", quote(v.Tag), quote(v.Value), label)
+	case naptrData:
+		return fmt.Sprintf("%d %d %s %s %s %s", v.Order, v.Preference, quote(v.Flags), quote(v.Service), quote(v.Regexp), quote(v.Replacement))
+	case sshfpData:
+		return fmt.Sprintf("%d %d %s", v.Algorithm, v.FingerprintType, v.Fingerprint)
+	case tlsaData:
+		return fmt.Sprintf("%d %d %d %s", v.CertificateUsage, v.Selector, v.MatchingType, quote(v.CertificateData))
+	case locData:
+		return fmt.Sprintf("%s (%d, %d) (%s, %s, %s)", v.Size, v.HorizontalPrecision, v.VerticalPrecision, v.Latitude, v.Longitude, v.Altitude)
+	case optRecord:
+		parts := make([]string, len(v.Options))
+		for i, opt := range v.Options {
+			parts[i] = fmt.Sprintf("{%d %v}", opt.Code, opt.Data)
+		}
+		return fmt.Sprintf("%d %d %d %d [%s]", v.UDPPSize, v.ExtCode, v.Version, v.Flags, strings.Join(parts, ", "))
+	case unknownData:
+		nums := make([]string, len(v.Bytes))
+		for i, b := range v.Bytes {
+			nums[i] = strconv.Itoa(int(b))
+		}
+		return strings.Join(nums, " ")
+	default:
+		return ""
+	}
+}
+
+func formatRRDuration(seconds uint32, asSeconds bool) string {
+	if asSeconds {
+		return strconv.FormatUint(uint64(seconds), 10)
+	}
+	return formatCompactDuration(seconds)
+}
+
+func formatCompactDuration(seconds uint32) string {
+	total := int64(seconds)
+	days := total / 86400
+	total %= 86400
+	hours := total / 3600
+	total %= 3600
+	mins := total / 60
+	secs := total % 60
+	switch {
+	case days > 0:
+		return fmt.Sprintf("%dd%dh%02dm%02ds", days, hours, mins, secs)
+	case hours > 0:
+		return fmt.Sprintf("%dh%02dm%02ds", hours, mins, secs)
+	case mins > 0:
+		return fmt.Sprintf("%dm%02ds", mins, secs)
+	default:
+		return fmt.Sprintf("%ds", secs)
+	}
+}
+
+func quote(s string) string {
+	return strconv.Quote(s)
+}
+
+func renderJSON(results []result, opts options, total time.Duration) jsonEnvelope {
+	env := jsonEnvelope{
+		Responses: make([]jsonResponse, 0, len(results)),
+	}
+	if opts.time {
+		ms := total.Milliseconds()
+		env.Duration = &jsonDuration{Secs: ms / 1000, Millis: ms % 1000}
+	}
+	for _, res := range results {
+		if res.resp == nil {
+			continue
+		}
+		jr := jsonResponse{
+			Queries:     make([]jsonQuestion, 0, len(res.resp.Questions)),
+			Answers:     make([]jsonRR, 0),
+			Authorities: make([]jsonRR, 0),
+			Additionals: make([]jsonRR, 0),
+		}
+		for _, q := range res.resp.Questions {
+			jr.Queries = append(jr.Queries, jsonQuestion{
+				Name:  q.Name,
+				Class: className(q.Class),
+				Type:  typeName(q.Type),
+			})
+		}
+		for _, record := range res.resp.Answers {
+			if record.Type == 41 && opts.edns != ednsShow {
+				continue
+			}
+			jr.Answers = append(jr.Answers, jsonRecord(record))
+		}
+		for _, record := range res.resp.Authorities {
+			if record.Type == 41 && opts.edns != ednsShow {
+				continue
+			}
+			jr.Authorities = append(jr.Authorities, jsonRecord(record))
+		}
+		for _, record := range res.resp.Additionals {
+			if record.Type == 41 && opts.edns != ednsShow {
+				continue
+			}
+			jr.Additionals = append(jr.Additionals, jsonRecord(record))
+		}
+		env.Responses = append(env.Responses, jr)
+	}
+	return env
+}
+
+func jsonRecord(record rr) jsonRR {
+	if record.Type == 41 {
+		opt, _ := record.Data.(optRecord)
+		data := struct {
+			Version uint8        `json:"version"`
+			Data    []jsonOption `json:"data"`
+		}{
+			Version: opt.Version,
+			Data:    make([]jsonOption, 0, len(opt.Options)),
+		}
+		for _, o := range opt.Options {
+			data.Data = append(data.Data, jsonOption{Code: o.Code, Data: append([]byte(nil), o.Data...)})
+		}
+		return jsonRR{
+			Name: record.Name,
+			Type: "OPT",
+			Data: data,
+		}
+	}
+	return jsonRR{
+		Name:  record.Name,
+		Class: className(record.Class),
+		TTL:   record.TTL,
+		Type:  typeName(record.Type),
+		Data:  jsonRData(record),
+	}
+}
+
+type jsonOption struct {
+	Code uint16 `json:"code"`
+	Data []byte `json:"data"`
+}
+
+func jsonRData(record rr) any {
+	switch v := record.Data.(type) {
+	case aData:
+		return struct {
+			Address string `json:"address"`
+		}{v.Address}
+	case aaaaData:
+		return struct {
+			Address string `json:"address"`
+		}{v.Address}
+	case cnameData:
+		return struct {
+			Domain string `json:"domain"`
+		}{v.Domain}
+	case nsData:
+		return struct {
+			Nameserver string `json:"nameserver"`
+		}{v.Nameserver}
+	case ptrData:
+		return struct {
+			CNAME string `json:"cname"`
+		}{v.CNAME}
+	case mxData:
+		return struct {
+			Preference uint16 `json:"preference"`
+			Exchange   string `json:"exchange"`
+		}{v.Preference, v.Exchange}
+	case txtData:
+		return struct {
+			Messages []string `json:"messages"`
+		}{v.Messages}
+	case hinfoData:
+		return struct {
+			CPU string `json:"cpu"`
+			OS  string `json:"os"`
+		}{v.CPU, v.OS}
+	case soaData:
+		return struct {
+			MName string `json:"mname"`
+		}{v.MName}
+	case srvData:
+		return struct {
+			Priority uint16 `json:"priority"`
+			Weight   uint16 `json:"weight"`
+			Port     uint16 `json:"port"`
+			Target   string `json:"target"`
+		}{v.Priority, v.Weight, v.Port, v.Target}
+	case caaData:
+		return struct {
+			Critical bool   `json:"critical"`
+			Tag      string `json:"tag"`
+			Value    string `json:"value"`
+		}{v.Critical, v.Tag, v.Value}
+	case naptrData:
+		return struct {
+			Order       uint16 `json:"order"`
+			Flags       string `json:"flags"`
+			Service     string `json:"service"`
+			Regex       string `json:"regex"`
+			Replacement string `json:"replacement"`
+		}{v.Order, v.Flags, v.Service, v.Regexp, v.Replacement}
+	case sshfpData:
+		return struct {
+			Algorithm       uint8  `json:"algorithm"`
+			FingerprintType uint8  `json:"fingerprint_type"`
+			Fingerprint     string `json:"fingerprint"`
+		}{v.Algorithm, v.FingerprintType, v.Fingerprint}
+	case tlsaData:
+		return struct {
+			CertificateUsage uint8  `json:"certificate_usage"`
+			Selector         uint8  `json:"selector"`
+			MatchingType     uint8  `json:"matching_type"`
+			CertificateData  string `json:"certificate_data"`
+		}{v.CertificateUsage, v.Selector, v.MatchingType, v.CertificateData}
+	case locData:
+		return struct {
+			Size      string `json:"size"`
+			Precision struct {
+				Horizontal uint8 `json:"horizontal"`
+				Vertical   uint8 `json:"vertical"`
+			} `json:"precision"`
