func run(args []string, stdout, stderr io.Writer) int {
	opts, err := parseOptions(args)
	if err != nil {
		fmt.Fprintf(stderr, "dog: Invalid options: %s\n", err.Error())
		return exitOptions
	}

	if opts.help {
		io.WriteString(stdout, helpText)
		return exitOK
	}
	if opts.version {
		io.WriteString(stdout, versionText)
		return exitOK
	}
	if len(opts.queries) == 0 {
		io.WriteString(stdout, helpText)
		return exitOptions
	}

	specs, code, err := buildSpecs(opts)
	if err != nil {
		if code == exitOptions {
			fmt.Fprintf(stderr, "dog: Invalid options: %s\n", err.Error())
		} else {
			fmt.Fprintf(stderr, "Error [nameserver]: %s\n", err.Error())
		}
		return code
	}

	start := time.Now()
	results := make([]result, 0, len(specs))
	hadNetworkError := false
	for _, spec := range specs {
		resp, elapsed, err := executeQuery(spec, opts)
		if err != nil {
			hadNetworkError = true
			fmt.Fprintf(stderr, "Error [network]: %s\n", err.Error())
			results = append(results, result{spec: spec, err: err, duration: elapsed})
			continue
		}
		results = append(results, result{spec: spec, resp: resp, duration: elapsed})
	}
	totalDuration := time.Since(start)

	if opts.short {
		lines := renderShort(results)
		if len(lines) == 0 {
			io.WriteString(stdout, "No results\n")
			if hadNetworkError {
				return exitNetwork
			}
			return exitShortNoResults
		}
		for _, line := range lines {
			fmt.Fprintln(stdout, line)
		}
		if hadNetworkError {
			return exitNetwork
		}
		return exitOK
	}

	if opts.json {
		env := renderJSON(results, opts, totalDuration)
		data, err := json.Marshal(env)
		if err != nil {
			fmt.Fprintf(stderr, "Error [network]: %s\n", err.Error())
			return exitNetwork
		}
		fmt.Fprintln(stdout, string(data))
		if hadNetworkError {
			return exitNetwork
		}
		return exitOK
	}

	renderText(stdout, results, opts, totalDuration)
	if hadNetworkError {
		return exitNetwork
	}
	return exitOK
}

func parseOptions(args []string) (options, error) {
	opts := options{
		color: "automatic",
		edns:  ednsHide,
	}

	i := 0
	positional := make([]string, 0)
	stop := false
	for i < len(args) {
		arg := args[i]
		if stop {
			positional = append(positional, arg)
			i++
			continue
		}
		if arg == "--" {
			stop = true
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name, value, hasValue := splitLong(arg)
			switch name {
			case "help":
				opts.help = true
			case "version":
				opts.version = true
			case "query":
				if !hasValue {
					i++
					if i >= len(args) {
						return opts, errors.New("Missing value for option --query")
					}
					value = args[i]
				}
				opts.queries = append(opts.queries, value)
			case "type":
				if !hasValue {
					i++
					if i >= len(args) {
						return opts, errors.New("Missing value for option --type")
					}
					value = args[i]
				}
				code, ok := parseTypeToken(value)
				if !ok {
					return opts, fmt.Errorf("Invalid query type %q", value)
				}
				opts.typeCodes = append(opts.typeCodes, code)
			case "class":
				if !hasValue {
					i++
					if i >= len(args) {
						return opts, errors.New("Missing value for option --class")
					}
					value = args[i]
				}
				code, ok := parseClassToken(value)
				if !ok {
					return opts, fmt.Errorf("Invalid query class %q", value)
				}
				opts.classCodes = append(opts.classCodes, code)
			case "nameserver":
				if !hasValue {
					i++
					if i >= len(args) {
						return opts, errors.New("Missing value for option --nameserver")
					}
					value = args[i]
				}
				opts.nameservers = append(opts.nameservers, value)
			case "udp":
				opts.transports = appendTransport(opts.transports, transportUDP)
			case "tcp":
				opts.transports = appendTransport(opts.transports, transportTCP)
			case "tls":
				opts.transports = appendTransport(opts.transports, transportTLS)
			case "https":
				opts.transports = appendTransport(opts.transports, transportHTTPS)
			case "short":
				opts.short = true
			case "json":
				opts.json = true
			case "color", "colour":
				if !hasValue {
					i++
					if i >= len(args) {
						return opts, errors.New("Missing value for option --color")
					}
					value = args[i]
				}
				opts.color = value
			case "seconds":
				opts.seconds = true
			case "time":
				opts.time = true
			case "edns":
				if !hasValue {
					i++
					if i >= len(args) {
						return opts, errors.New("Missing value for option --edns")
					}
					value = args[i]
				}
				switch value {
				case "hide":
					opts.edns = ednsHide
				case "show":
					opts.edns = ednsShow
				case "disable":
					opts.edns = ednsDisable
				default:
					return opts, fmt.Errorf("Invalid EDNS setting %q", value)
				}
			case "txid":
				if !hasValue {
					i++
					if i >= len(args) {
						return opts, errors.New("Missing value for option --txid")
					}
					value = args[i]
				}
				v, ok := parseUint16Strict(value)
				if !ok {
					return opts, fmt.Errorf("Invalid transaction ID %q", value)
				}
				opts.txid = &v
			default:
				return opts, fmt.Errorf("Unrecognized option: %q", strings.TrimPrefix(name, "--"))
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "-") && arg != "-" {
			if arg == "-?" {
				opts.help = true
				i++
				continue
			}
			if arg == "-v" {
				opts.version = true
				i++
				continue
			}
			if arg == "-1" {
				opts.short = true
				i++
				continue
			}
			cluster := arg[1:]
			consumedValue := false
			for len(cluster) > 0 {
				ch := cluster[0]
				cluster = cluster[1:]
				switch ch {
				case '?':
					opts.help = true
				case 'v':
					opts.version = true
				case '1':
					opts.short = true
				case 'J':
					opts.json = true
				case 'U':
					opts.transports = appendTransport(opts.transports, transportUDP)
				case 'T':
					opts.transports = appendTransport(opts.transports, transportTCP)
				case 'S':
					opts.transports = appendTransport(opts.transports, transportTLS)
				case 'H':
					opts.transports = appendTransport(opts.transports, transportHTTPS)
				case 'q', 't', 'n', 'Z':
