func rcodeText(code uint16) string {
	switch code {
	case 1:
		return "Format Error"
	case 2:
		return "Server Failure"
	case 3:
		return "NXDomain"
	case 4:
		return "Not Implemented"
	case 5:
		return "Refused"
	default:
		return fmt.Sprintf("Error %d", code)
	}
}

