func className(code uint16) string {
	if name, ok := classNames[code]; ok {
		return name
	}
	return strconv.Itoa(int(code))
}

func parseTypeToken(s string) (uint16, bool) {
	u := strings.ToUpper(s)
	if code, ok := typeLookup[u]; ok {
		return code, true
	}
	if strings.HasPrefix(u, "TYPE") {
		return parseUint16Strict(strings.TrimPrefix(u, "TYPE"))
	}
	return parseUint16Strict(u)
}

func parseClassToken(s string) (uint16, bool) {
	u := strings.ToUpper(s)
	if code, ok := classLookup[u]; ok {
		return code, true
	}
	if strings.HasPrefix(u, "CLASS") {
		return parseUint16Strict(strings.TrimPrefix(u, "CLASS"))
	}
	return 0, false
}

